<?php $e = static fn($value): string => htmlspecialchars((string) ($value ?? ''), ENT_QUOTES, 'UTF-8'); ?>
<section class="page-hero page-hero-compact"><div><p class="eyebrow">Taam Bledi</p><h1>Suivi des plantations</h1><p>Consultez et gérez les observations des plantations.</p></div><a class="button button-light" href="index.php?action=plantations">Plantations</a></section>
<?php if ($plantation): ?>
    <section class="page-hero page-hero-compact"><div><p class="eyebrow">Suivi de la plantation</p><h1><?= $e($plantation['nom']) ?></h1><p><?= $e($plantation['adresse']) ?> · <?= $e($plantation['varieteNom'] ?: 'Variété non précisée') ?></p></div><a class="button button-light" href="index.php?action=suivi_create&amp;plantation=<?= (int) $plantation['idPlantation'] ?>">+ Ajouter un suivi</a></section>
    <p><a href="index.php?action=plantation_show&amp;id=<?= (int) $plantation['idPlantation'] ?>">← Détails de la plantation</a></p>
<?php else: ?>
    <section class="page-hero page-hero-compact"><div><p class="eyebrow">Taam Bledi</p><h1>Suivi des plantations</h1><p>Choisissez une plantation pour consulter ses observations.</p></div><a class="button button-light" href="index.php?action=plantations">Plantations</a></section>
<?php endif; ?>
<?php if (!$suivis): ?><section class="empty-state"><h2>Aucun suivi pour le moment</h2><p><?= $plantation ? 'Ajoutez la première observation de cette plantation.' : 'Ouvrez une plantation pour enregistrer une observation.' ?></p></section><?php else: ?><section class="history-list"><?php foreach ($suivis as $s): ?><article class="history-entry"><div class="section-heading"><h3><?= $e($plantation ? $s['dateSuivi'] : $s['plantationNom']) ?> · <?= $e($s['etat']) ?></h3><?php if (!$plantation): ?><a href="index.php?action=suivis&amp;plantation=<?= (int) $s['idPlantation'] ?>">Voir cette plantation →</a><?php else: ?><span><?= $e($s['dateSuivi']) ?></span><?php endif; ?></div><?php if ($s['arrosage'] !== ''): ?><p><strong>Arrosage :</strong> <?= $e($s['arrosage']) ?></p><?php endif; ?><?php if ($s['observation'] !== ''): ?><p><strong>Observation :</strong> <?= nl2br($e($s['observation'])) ?></p><?php endif; ?><?php if ($s['photo'] !== ''): ?><p><strong>Photo :</strong> <?= $e($s['photo']) ?></p><?php endif; ?><?php if ($s['diagnosticIA'] !== ''): ?><p><strong>Diagnostic IA :</strong> <?= nl2br($e($s['diagnosticIA'])) ?></p><?php endif; ?><div class="form-actions"><a href="index.php?action=suivi_update&amp;id=<?= (int) $s['idSuivi'] ?>">Modifier</a><form method="post" action="index.php?action=suivi_delete" data-confirm="Supprimer ce suivi ?"><input type="hidden" name="csrf_token" value="<?= $e($csrfToken ?? '') ?>"><input type="hidden" name="id" value="<?= (int) $s['idSuivi'] ?>"><button class="text-button" type="submit">Supprimer</button></form></div></article><?php endforeach; ?></section><?php endif; ?>
